import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(12))
G.add_edges_from([(7,9), (1,3), (0,8), (6,11), (1,6), (3,11), (4,9), (4,11), (6,8), (10,11), (5,11), (1,10), (2,6)])
while True:
    min_degree = min(G.degree(node) for node in G.nodes)
    if min_degree >= 3:
        break
    for u in G.nodes:
        if G.degree(u) == min_degree:
            for v in G.nodes:
                if u < v and not G.has_edge(u, v):
                    G.add_edge(u, v)
                    break
            break
print([(u, v) for u in G.nodes for v in G.nodes if u < v and G.has_edge(u, v)])
